// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.prank(address(this));
        c.transferOwnership(actor);

        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            assertTrue(!(newOwner == address(0)) && c.owner() == newOwner, "ownership invariant");
        } catch {
            assertTrue(true);
        }
    }
}
